import { defineEntity, p, type InferEntity } from "@mikro-orm/core";
import { WagerTransactionRecord } from "../../wagering/infrastructure/wager-transaction.record";
import { WalletRecord } from "./wallet.record";

/** `seq` (identity, used as the ledger cursor) is generated by Postgres and read via SQL only. */
export const WalletLedgerEntryRecord = defineEntity({
  name: "WalletLedgerEntryRecord",
  tableName: "wallet_ledger_entries",
  properties: {
    id: p.uuid().primary(),
    wallet: () => p.manyToOne(WalletRecord).mapToPk(),
    transaction: () => p.manyToOne(WagerTransactionRecord).mapToPk(),
    direction: p.string().length(6),
    amount: p.decimal("string").precision(20).scale(2),
    currency: p.string().columnType("char(3)"),
    balanceBefore: p.decimal("string").precision(20).scale(2),
    balanceAfter: p.decimal("string").precision(20).scale(2),
    createdAt: p.datetime().columnType("timestamptz"),
  },
});
export type WalletLedgerEntryRecord = InferEntity<typeof WalletLedgerEntryRecord>;
